sqlReaderQuery.value:
@concat(
    'SELECT MAX(LastModifiedDate) AS NewWatermark ',
    'FROM dbo.FactSales ',
    'WHERE LastModifiedDate > ''',
    if(
        empty(activity('Lookup_FactSales_Watermark').output.firstRow.LastWatermark),
        '1900-01-01 00:00:00',
        activity('Lookup_FactSales_Watermark').output.firstRow.LastWatermark
    ),
    ''''
)
